def count_binary_seq(n):
    if n == 1:
        return 2
    # Initialize DP table: dp[i][j][k] represents count of binary sequences of length 2i
    # where sum of first i bits is j and sum of last i bits is k.
    # We optimize space by using dp[j][k] for current i and previous i-1
    dp_prev = [[0]*(2*n + 1) for _ in range(2*n + 1)]
    dp_prev[1][0] = 1  # Base case: first 1 bit is 1 with sum 1 and last 1 bit is 0 with sum 0
    dp_prev[0][1] = 1  # Base case: first 1 bit is 0 with sum 0 and last 1 bit is 1 with sum 1

    # Fill the DP table for all possible sums of first n and last n bits
    for i in range(2, n + 1):
        dp_current = [[0]*(2*i + 1) for _ in range(2*i + 1)]
        for j in range(0, i + 1):
            for k in range(0, i + 1):
                # Previous state could be adding a '0' bit
                dp_current[j][k] += dp_prev[j][k]  # Adding a '0' does not change the sum
                # Or adding a '1' bit
                if (j > 0):
                    dp_current[j][k] += dp_prev[j - 1][k]  # Adding a '1' to first part reduces its sum
                if (k > 0):
                    dp_current[j][k] += dp_prev[j][k - 1]  # Adding a '1' to last part reduces its sum
        dp_prev = dp_current

    # The result is the sum of sequences where the first and last n bits have the same sum
    return sum(dp_prev[j][j] for j in range(0, n + 1))
