def count_binary_seq(n):
    if n == 0:
        return 1
    # Initialize DP table
    dp = [[0]*(2*n + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # Base case: empty sequence has sum 0

    for i in range(1, n + 1):
        for j in range(2 * i + 1):
            # Number of ways to have sum 'j' in first i bits
            if j - 1 >= 0:
                dp[i][j] += dp[i-1][j-1]
            if j + 1 <= 2 * i:
                dp[i][j] += dp[i-1][j+1]

    total = 0
    for j in range(n):
        # For each possible sum 'j' in first n bits, find the same sum in last n bits
        if 2 * n - j >= 0:
            total += dp[n][j] * dp[n][2 * n - j]

    return total
